      ('public.plan_orders_create(jsonb,text,text)', ARRAY[h_c1a], ARRAY[h_c1b], '2326a1dc062d08b71fb0d8f28dc36151'),
      ('public.plan_h_order_summary(jsonb)', ARRAY[h_s1a], ARRAY[h_s1b], '73e59554178fbdbebdf9544994dfa5e5'),
      ('public.plan_shipment_problem(bigint)', ARRAY[h_q1a], ARRAY[h_q1b], 'eb19f0bd29b5cbc7843d2145be858727'),
      ('public.plan_h_resize(bigint,numeric,text,text)', ARRAY[h_r1a], ARRAY[h_r1b], 'b5adbb199b7bff4d7f0fc3d70a34cb7d'),
      ('public.plan_h_put(jsonb,jsonb,text,text,bigint[])', ARRAY[h_p1a], ARRAY[h_p1b], '7ed550b6cafa5bf2fb88d65ba2c112bf'),
      ('public.plan_split_piece(jsonb,text,text)', ARRAY[h_x1a], ARRAY[h_x1b], '4a61314bbab1492431750fd75cffdb14'),
      ('public.plan_h_pallet_sync(bigint[],text,text)', ARRAY[h_f1a], ARRAY[h_f1b], '8310af0c7711ba2fcfda96955ae5f7a5')) g(sig, a, b, m) LOOP
    SELECT * INTO p FROM pg_proc WHERE oid = to_regprocedure(v_g.sig);
    IF p.proconfig IS DISTINCT FROM ARRAY['search_path=public'] THEN
      RAISE EXCEPTION '080: % has no search_path=public - stop', v_g.sig;
    END IF;
    v_new := p.prosrc;
    FOR v_h IN SELECT * FROM unnest(v_g.a, v_g.b) h(a, b) LOOP
      IF (length(v_new) - length(replace(v_new, v_h.a, ''))) <> length(v_h.a) THEN
        RAISE EXCEPTION '080: a patch target is not in % exactly once - stop', v_g.sig;
      END IF;
      v_new := replace(v_new, v_h.a, v_h.b);
    END LOOP;
    IF md5(v_new) <> v_g.m THEN
      RAISE EXCEPTION '080: the generated text of % is not the one measured (md5 %) - stop', v_g.sig, md5(v_new);
    END IF;
    -- CREATE OR REPLACE keeps the oid, owner and grants (the Worker's EXECUTE on the plan_* it calls)
    EXECUTE format('CREATE OR REPLACE FUNCTION %s(%s) RETURNS %s LANGUAGE %s %s %s SET search_path = public AS %L',
      split_part(v_g.sig, '(', 1), pg_get_function_arguments(p.oid), pg_get_function_result(p.oid),
      (SELECT lanname FROM pg_language WHERE oid = p.prolang),
      CASE p.provolatile WHEN 'i' THEN 'IMMUTABLE' WHEN 's' THEN 'STABLE' ELSE 'VOLATILE' END,
      CASE WHEN p.prosecdef THEN 'SECURITY DEFINER' ELSE 'SECURITY INVOKER' END, v_new);
    IF (SELECT md5(prosrc) FROM pg_proc WHERE oid = p.oid) <> v_g.m THEN
      RAISE EXCEPTION '080 proof: % does not hold its generated text', v_g.sig;
    END IF;
  END LOOP;

  -- ===== PART 3: THE MONEY VIEWS = 073's TEXT + HUNKS (in dependency order; new columns only at the end) =====
  FOR v_g IN SELECT * FROM (VALUES
      ('ct_v_v5_revenue', v_v5_0, ARRAY[h_v1a, h_v2a, h_v3a], ARRAY[h_v1b, h_v2b, h_v3b]),
      ('ct_v_rt_revenue', v_rev_0, ARRAY[h_r5a, h_r6a, h_r7a, h_r8a], ARRAY[h_r5b, h_r6b, h_r7b, h_r8b]),
      ('ct_v_rt_pnl', v_pnl_0, ARRAY[h_n1a], ARRAY[h_n1b])) g(v, t, a, b) LOOP
    v_new := v_g.t || E'\n';
    FOR v_h IN SELECT * FROM unnest(v_g.a, v_g.b) h(a, b) LOOP
      IF (length(v_new) - length(replace(v_new, v_h.a, ''))) <> length(v_h.a) THEN
        RAISE EXCEPTION '080: a patch target is not in % exactly once - stop', v_g.v;
      END IF;
      v_new := replace(v_new, v_h.a, v_h.b);
    END LOOP;
    -- CREATE OR REPLACE keeps the owner, the grants (service_role and the auditor's runner, 073 PART 5) and every
    -- view that reads this one
    EXECUTE format('CREATE OR REPLACE VIEW public.%I AS %s', v_g.v, v_new);
  END LOOP;

  -- ===== PART 4: B-100 (text = tms-auditor/checks/B-100.sql; md5-proven below) =====
  INSERT INTO monitoring.checks (id, title, flows, sql_text, ids_sql, entity_table, red_op, red_value, baseline, severity,
    schedule_tag, is_queue, impact, next_step, exceptions, tolerance, enabled, disabled_reason) VALUES
    ($m$B-100$m$,
     convert_from(decode('zpXOuM69zrnOus6uIHY1IM68zrUgzqzOs869z4nPg8+EzrXPgiDPgM6xzrvOrc+EzrXPgg==', 'base64'), 'UTF8'),
     ARRAY[$m$F-23$m$,$m$F-36$m$]::text[],
     $m$SELECT count(DISTINCT n.id) FROM national_orders n JOIN shipments s ON s.nat_order_id = n.id
 WHERE n.deleted_at IS NULL AND s.deleted_at IS NULL AND s.order_stop_id IS NULL AND s.pallets IS NULL$m$,
     $m$SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM (SELECT DISTINCT n.legacy_id AS x FROM national_orders n JOIN shipments s ON s.nat_order_id = n.id
 WHERE n.deleted_at IS NULL AND s.deleted_at IS NULL AND s.order_stop_id IS NULL AND s.pallets IS NULL ORDER BY 1 LIMIT 50) s$m$,
     $m$national_orders$m$,
     $m$>$m$,
     0,
     NULL,
     $m$P2$m$,
     $m$daily$m$,
     true,
     convert_from(decode('', 'base64'), 'UTF8'),
     convert_from(decode('RGlzcGF0Y2hlciDOtc64zr3Ouc66z47OvTogz4DOsc67zq3PhM61z4Igz4PPhM63zr0gz4DOsc+BzrHOs86zzrXOu86vzrEgKM6VzrLOtM6/zrzOsc60zrnOsc6vzr8gzpXOuM69zrnOus+Ozr0g4oaSIM6azrHPgc+Ezq3Ou86xIM+AzrHPgc6xzrPOs861zrvOr86xz4Ig4oaSIM6Vz4DOtc6+zrXPgc6zzrHPg86vzrEpLg==', 'base64'), 'UTF8'),
     convert_from(decode('', 'base64'), 'UTF8'),
     NULL,
     true,
     NULL);

  -- ===== PART 5: PROOFS =====
  IF (SELECT attnotnull FROM pg_attribute WHERE attrelid = 'public.shipment_pieces'::regclass AND attname = 'pallets') THEN
    RAISE EXCEPTION '080 proof: shipment_pieces.pallets still refuses NULL';
  END IF;
  IF (SELECT string_agg(attname, ',' ORDER BY attnum) FROM pg_attribute WHERE attrelid = 'public.ct_v_v5_revenue'::regclass AND attnum > 0)
       <> 'kind,order_id,nat_order_id,piece_id,leg_id,rt_id,pallets,total,amount'
     OR (SELECT string_agg(attname, ',' ORDER BY attnum) FROM pg_attribute WHERE attrelid = 'public.ct_v_rt_revenue'::regclass AND attnum > 0)
       <> 'rt_id,revenue,revenue_intl,revenue_natl,revenue_missing'
     OR (SELECT attname FROM pg_attribute WHERE attrelid = 'public.ct_v_rt_pnl'::regclass AND attnum > 0 ORDER BY attnum DESC LIMIT 1)
       <> 'v5_revenue_missing' THEN
    RAISE EXCEPTION '080 proof: the money views do not have the columns 080 gives them';
  END IF;
  -- no v5 order is without price or pallets before 080 (both were refused): today's money does not move
  SELECT count(*) || ':' || md5(coalesce(string_agg(to_jsonb(x)::text, '|' ORDER BY x.piece_id, x.leg_id), '')) INTO v_fp1
    FROM public.ct_v_v5_revenue x
   WHERE x.nat_order_id IS NULL OR x.nat_order_id NOT IN (SELECT id FROM public.national_orders WHERE price IS NULL);
  SELECT v_fp1 || '/' || count(*) || ':' || md5(coalesce(string_agg((to_jsonb(r) - 'revenue_missing')::text, '|' ORDER BY r.rt_id), '')) INTO v_fp1
    FROM public.ct_v_rt_revenue r WHERE r.rt_id IN (SELECT l.rt_id FROM public.piece_legs l)
     AND r.rt_id NOT IN (SELECT l.rt_id FROM public.piece_legs l JOIN public.shipment_pieces sp ON sp.id = l.piece_id
                          JOIN public.shipments sh ON sh.id = sp.shipment_id JOIN public.national_orders o ON o.id = sh.nat_order_id
                         WHERE o.price IS NULL);
  IF v_fp1 IS DISTINCT FROM v_fp0 THEN
    RAISE EXCEPTION '080 proof: the v5 money moved (% -> %)', v_fp0, v_fp1;
  END IF;
  IF NOT has_table_privilege('service_role', 'public.ct_v_rt_pnl', 'SELECT') OR has_table_privilege('anon', 'public.ct_v_rt_pnl', 'SELECT')
     OR has_table_privilege('anon', 'public.ct_v_v5_revenue', 'SELECT') OR has_table_privilege('authenticated', 'public.ct_v_rt_revenue', 'SELECT') THEN
    RAISE EXCEPTION '080 proof: the rights on the money views changed';
  END IF;
  IF NOT has_function_privilege('service_role', 'public.plan_orders_create(jsonb,text,text)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'public.plan_split_piece(jsonb,text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION '080 proof: the Worker lost EXECUTE on a plan_* it calls';
  END IF;
  -- B-100: the file's text, the guard of monitoring.run_checks, run as the auditor's role: 0 today
  IF (SELECT md5(sql_text) <> '769cefd8a31d4434febaa768ca69da7c' OR md5(coalesce(ids_sql, '')) <> '8ba57ab205685ccfe04959ed3c720e93' OR NOT enabled
        FROM monitoring.checks WHERE id = 'B-100') THEN
    RAISE EXCEPTION '080 proof: B-100 is not the text (or the on/off) of its file';
  END IF;
  SELECT sql_text, ids_sql INTO v_sql, v_ids FROM monitoring.checks WHERE id = 'B-100';
  PERFORM monitoring.check_sql_guard(v_sql);
  PERFORM monitoring.check_sql_guard(v_ids);
  SET LOCAL ROLE tms_check_runner;
  EXECUTE v_sql INTO v_v;
  EXECUTE v_ids INTO STRICT v_a;
  RESET ROLE;
  IF v_v IS DISTINCT FROM 0 OR cardinality(v_a) IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION '080 proof: B-100 gives % (%) today, expected 0', v_v, v_a;
  END IF;
  SELECT count(*) INTO v_trg1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace ns ON ns.oid = c.relnamespace WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF v_trg1 <> v_trg0 THEN RAISE EXCEPTION '080 proof: triggers % -> % (080 adds none)', v_trg0, v_trg1; END IF;
  RAISE NOTICE '080 OK: pallets may be NULL on a root piece, price may be NULL, 7 functions patched, 3 money views, B-100, triggers %, v5 money unchanged (%)',
    v_trg1, v_fp1;
END;
  -- ===== what it did =====
  res := format('080 ran: pallets nullable %s, B-100 %s, create %s, pnl last column %s',
    CASE WHEN (SELECT NOT attnotnull FROM pg_attribute WHERE attrelid = 'public.shipment_pieces'::regclass AND attname = 'pallets') THEN 'yes' ELSE 'NO' END,
    CASE WHEN EXISTS (SELECT 1 FROM monitoring.checks WHERE id = 'B-100') THEN 'yes' ELSE 'NO' END,
    (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.plan_orders_create(jsonb,text,text)'::regprocedure),
    (SELECT attname FROM pg_attribute WHERE attrelid = 'public.ct_v_rt_pnl'::regclass AND attnum > 0 ORDER BY attnum DESC LIMIT 1));
  RAISE EXCEPTION 'DRY RUN 080 finished - EVERYTHING UNDONE, nothing kept. The block ran to its end  ||  %', res;
END
$dry$;
